		ValidSampleAndBinaryValueInDB GetValidSample(BusinessObjectFactory factory, Guid orgPk, Guid addressPk, byte[] binaryValue)
		{
			GetOrNew(factory, ObjectFactory.GetType<IOrgHeader>(), orgPk, item =>
			{
				var org = (IOrgHeader)item;
				org.Code = CodeFromGuid(orgPk);
				org.OH_IsPackDepot = true;
			});

			GetOrNew(factory, ObjectFactory.GetType<IOrgAddress>(), addressPk, item =>
			{
				var address = (IOrgAddress)item;
				address.OA_Address1 = "ADDRESS";
				address.OA_OH = orgPk;
			});

			var sample = new DepotAddressColorSound(factory) { Organisation = orgPk, Address = addressPk, Color = "123123123", MP3FileName = "A.mp3", MP3FileContent = ZBlob.FromAscii("asdasd") };
			var sampleCollection = new DepotAddressColorSoundCollection(factory);
			sampleCollection.Add(sample);

			return new ValidSampleAndBinaryValueInDB(sampleCollection, binaryValue);
		}

